def check_region(region: str) -> None:
    if not _REGION.match(region):
        raise ValidationError(f"invalid region {region!r}", field="region")

class TaxTable:
    """Tax rates in percent by region code (``"US-CA"``). ``default`` covers the rest."""

    rates: dict[str, Decimal] = field(default_factory=dict)
    default: Decimal = Decimal(0)
    exempt_categories: frozenset[str] = frozenset({"food", "books"})

    def rate(self, region: str) -> Decimal:
        if region in self.rates:
            return self.rates[region]
        country = region.split("-", 1)[0]
        return self.rates.get(country, self.default)

    def tax(self, amount: Money, region: str) -> Money:
        return amount.times(self.rate(region) / 100)

class Repository:
    """Typed access to the shop's records."""

    def __init__(self, store: RecordStore) -> None:
        self.store = store

    def save_product(self, p: Product) -> None:
        self.store.put(PRODUCTS, product_to_record(p))

    def product(self, sku: str) -> Product:
        return product_from_record(self.store.get(PRODUCTS, sku))

    def products(self, category: str | None = None) -> list[Product]:
        where = (lambda r: r.get("category") == category) if category else None
        return [product_from_record(r) for r in iter_records(self.store, PRODUCTS, where)]

    def save_customer(self, c: Customer) -> None:
        self.store.put(CUSTOMERS, customer_to_record(c))

    def customer(self, cid: str) -> Customer:
        return customer_from_record(self.store.get(CUSTOMERS, cid))

    def save_order(self, o: Order) -> None:
        self.store.put(ORDERS, o.to_dict())

    def order(self, oid: str) -> Order:
        r = self.store.get(ORDERS, oid)
        return self._order_from_record(r)

    def _order_from_record(self, r: dict) -> Order:
        lines = []
        for l in r["lines"]:
            p = self.product(l["sku"])
            lines.append(OrderLine(p, l["quantity"]))
        return Order(
            r["id"], self.customer(r["customer"]), lines, OrderStatus(r["status"]),
            date.fromisoformat(r["placed_on"]) if r.get("placed_on") else None,
            list(r.get("coupons", [])),
        )

    def orders(self, status: OrderStatus | None = None) -> list[Order]:
        where = (lambda r: r["status"] == status.value) if status else None
        return [self._order_from_record(r) for r in iter_records(self.store, ORDERS, where)]

class Product:
    sku: str
    name: str
    price: Money
    category: str = "general"
    taxable: bool = True

    def __post_init__(self) -> None:
        check_sku(self.sku)
        if not self.name.strip():
            raise ValidationError("name must not be empty", field="name")
        if self.price.minor < 0:
            raise ValidationError("price must not be negative", field="price")

class CouponBook:
    """The coupons a shop accepts, by code (case-insensitive)."""

    def __init__(self, coupons: list[Coupon] | None = None) -> None:
        self._by_code = {c.code.upper(): c for c in coupons or []}

    def add(self, coupon: Coupon) -> None:
        self._by_code[coupon.code.upper()] = coupon

    def get(self, code: str) -> Coupon | None:
        return self._by_code.get(code.strip().upper())

    def discounts_for(self, codes: list[str], subtotal: Money, tier: str, today: date) -> list[Discount]:
        """Discounts of the usable coupons among ``codes``; unknown or unusable codes are skipped."""
        out: list[Discount] = []
        seen: set[str] = set()
        for code in codes:
            c = self.get(code)
            if c is None or c.code.upper() in seen:
                continue
            seen.add(c.code.upper())
            if c.usable(subtotal, tier, today):
                out.append(c.discount(subtotal.currency))
        return out

class Order:
    id: str
    customer: Customer
    lines: list[OrderLine] = field(default_factory=list)
    status: OrderStatus = OrderStatus.DRAFT
    placed_on: date | None = None
    coupon_codes: list[str] = field(default_factory=list)

    @property
    def currency(self) -> str:
        return self.lines[0].product.price.currency if self.lines else "USD"

    def add(self, product: Product, quantity: int = 1) -> None:
        """Add ``quantity`` of ``product``, merging with an existing line for the same SKU."""
        if self.status is not OrderStatus.DRAFT:
            raise ValidationError("only draft orders can change", field="status")
        for i, line in enumerate(self.lines):
            if line.product.sku == product.sku:
                self.lines[i] = OrderLine(product, line.quantity + quantity)
                return
        self.lines.append(OrderLine(product, quantity))

    def remove(self, sku: str) -> None:
        if self.status is not OrderStatus.DRAFT:
            raise ValidationError("only draft orders can change", field="status")
        self.lines = [line for line in self.lines if line.product.sku != sku]

    @property
    def subtotal(self) -> Money:
        return total((line.subtotal for line in self.lines), self.currency)

    def item_count(self) -> int:
        return sum(line.quantity for line in self.lines)

    def to_dict(self) -> dict:
        return {
            "id": self.id,
            "customer": self.customer.id,
            "status": self.status.value,
            "placed_on": self.placed_on.isoformat() if self.placed_on else None,
            "coupons": list(self.coupon_codes),
            "lines": [
                {"sku": l.product.sku, "quantity": l.quantity, "price": l.product.price.minor}
                for l in self.lines
            ],
        }

def allocate(self, parts: int) -> list[Money]:
    """Split into ``parts`` amounts that sum exactly to this one."""
    if parts <= 0:
        raise ValidationError("parts must be positive", field="parts")
    base, rest = divmod(self.minor, parts)
    return [Money(base + (1 if i < rest else 0), self.currency) for i in range(parts)]

class Workflow:
    def __init__(self, ledger: Ledger, bus: EventBus | None = None, coupons: CouponBook | None = None) -> None:
        self.ledger = ledger
        self.bus = bus or EventBus()
        self.coupons = coupons or CouponBook()

    def _move(self, order: Order, to: OrderStatus) -> None:
        if to not in _ALLOWED[order.status]:
            raise ValidationError(f"cannot go from {order.status.value} to {to.value}", field="status")
        order.status = to
        self.bus.publish(f"order.{to.value}", {"id": order.id})

    def place(self, order: Order, on: date) -> None:
        if not order.lines:
            raise ValidationError("an order needs at least one line", field="lines")
        order.placed_on = on
        self._move(order, OrderStatus.PLACED)

    def pay(self, order: Order, on: date) -> None:
        q = quote_order(order, self.coupons, today=on)
        self._move(order, OrderStatus.PAID)
        self.ledger.record_sale(on, order.id, q)

    def ship(self, order: Order) -> None:
        self._move(order, OrderStatus.SHIPPED)

    def cancel(self, order: Order) -> None:
        self._move(order, OrderStatus.CANCELLED)
